int main() {
    int N;
    scanf("%d", &N);

    // Read C
    int C[200][200];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &C[i][j]);
        }
    }

    // Compute rank of C over GF(2)
    int mat[200][200];
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            mat[i][j] = C[i][j];

    int rank = 0;
    int col = 0;
    int where[200];
    for (int i = 0; i < N; i++) where[i] = -1;

    for (col = 0; col < N && rank < N; col++) {
        int sel = -1;
        for (int i = rank; i < N; i++) {
            if (mat[i][col]) {
                sel = i;
                break;
            }
        }
        if (sel == -1) continue;
        // swap rows
        for (int j = col; j < N; j++) {
            int tmp = mat[sel][j];
            mat[sel][j] = mat[rank][j];
            mat[rank][j] = tmp;
        }
        where[rank] = col;
        // eliminate other rows
        for (int i = 0; i < N; i++) {
            if (i != rank && mat[i][col]) {
                for (int j = col; j < N; j++) {
                    mat[i][j] ^= mat[rank][j];
                }
            }
        }
        rank++;
    }

    int r = rank;

    // Precompute powers of 2
    long long pow2[401];
    pow2[0] = 1;
    for (int i = 1; i <= 2*N; i++) {
        pow2[i] = pow2[i-1] * 2 % MOD;
    }

    // Precompute number of NxN matrices of each rank over GF(2)
    long long cnt_rank[201];
    for (int k = 0; k <= N; k++) {
        if (k == 0) {
            cnt_rank[0] = 1;
            continue;
        }
        long long num = 1, den = 1;
        for (int i = 0; i < k; i++) {
            num = num * ((pow2[N] - pow2[i] + MOD) % MOD) % MOD;
            num = num * ((pow2[N] - pow2[i] + MOD) % MOD) % MOD;
            den = den * ((pow2[k] - pow2[i] + MOD) % MOD) % MOD;
        }
        cnt_rank[k] = num * modpow(den, MOD-2) % MOD;
    }

    long long ans = 0;
    for (int s = r; s <= N; s++) {
        // Number of A with rank s such that C's column space is contained in A's column space
        // Column space of C has dimension r, must be subspace of A's column space
        // Number of ways to pick extra s-r independent columns from remaining N dimensions:
        // product_{i=0}^{s-r-1} (2^N - 2^{r+i}) / (2^{s} - 2^{r+i})? Actually let's compute directly:

        // For A of rank s, number of such A containing fixed r-dim subspace:
        long long ways = 1;
        // Choose the remaining s-r basis vectors from N-dim space outside the r-dim subspace
        long long space_dim = N;
        long long fixed_dim = r;
        for (int i = 0; i < s - r; i++) {
            ways = ways * ((pow2[space_dim] - pow2[fixed_dim + i] + MOD) % MOD) % MOD;
        }
        // Divide by number of ways to choose basis for the s-dim space that extends the fixed r-dim subspace
        for (int i = 0; i < s - r; i++) {
            ways = ways * modpow((pow2[s] - pow2[r + i] + MOD) % MOD, MOD-2) % MOD;
        }
        // Multiply by number of A with exactly rank s
        ways = ways * cnt_rank[s] % MOD;

        // For each such A, number of B is 2^{N*(N-s)}
        ways = ways * modpow(2, (long long)N*(N-s)) % MOD;

        ans = (ans + ways) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

