#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    unsigned long long *rows = (unsigned long long *)calloc(N, sizeof(unsigned long long));
    if (!rows) return 0;

    for (int i = 0; i < N; i++) {
        char s[70];
        scanf("%s", s);
        unsigned long long mask = 0;
        for (int j = 0; j < N; j++) {
            if (s[j] == '1') mask |= (1ULL << j);
        }
        rows[i] = mask;
    }

    /* Gaussian elimination over GF(2) to find rank of C */
    int rank = 0;
    for (int col = 0; col < N; col++) {
        int pivot = -1;
        for (int r = rank; r < N; r++) {
            if ((rows[r] >> col) & 1ULL) {
                pivot = r;
                break;
            }
        }
        if (pivot == -1) continue;

        unsigned long long tmp = rows[rank];
        rows[rank] = rows[pivot];
        rows[pivot] = tmp;

        for (int r = 0; r < N; r++) {
            if (r != rank && ((rows[r] >> col) & 1ULL)) {
                rows[r] ^= rows[rank];
            }
        }
        rank++;
    }

    free(rows);

    /*
      Number of pairs (A,B) with AB = C over GF(2) depends only on r = rank(C).

      For each possible k = rank(A), where r <= k <= N:
      - choose image subspace W of dimension k containing Im(C):
          Gaussian binomial [N-r choose k-r]_2
      - choose a surjective map A: GF(2)^N -> W:
          prod_{i=0}^{k-1} (2^N - 2^i)
      - for fixed A, number of B with AB=C:
          2^{N(N-k)}

      Summing and simplifying:
          ans = sum_{k=r}^N [N-r choose k-r]_2
                            * prod_{i=0}^{k-1}(2^N-2^i)
                            * 2^{N(N-k)}
    */

    long long pow2[65];
    pow2[0] = 1;
    for (int i = 1; i <= N; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

    long long ans = 0;

    for (int k = rank; k <= N; k++) {
        long long ways_subspace = 1;
        int a = N - rank;
        int b = k - rank;

        /* Gaussian binomial [a choose b]_2 */
        for (int i = 0; i < b; i++) {
            long long num = (pow2[a - i] - 1 + MOD) % MOD;
            long long den = (pow2[b - i] - 1 + MOD) % MOD;
            ways_subspace = ways_subspace * num % MOD;
            ways_subspace = ways_subspace * mod_pow(den, MOD - 2) % MOD;
        }

        long long ways_A = 1;
        for (int i = 0; i < k; i++) {
            long long term = (pow2[N] - pow2[i] + MOD) % MOD;
            ways_A = ways_A * term % MOD;
        }

        long long ways_B = mod_pow(2, 1LL * N * (N - k));

        long long add = ways_subspace;
        add = add * ways_A % MOD;
        add = add * ways_B % MOD;
        ans += add;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

