#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

// fast power mod
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

// rank over GF(2) for rows represented by bitsets in uint64 blocks
int rank_gf2(vector<vector<unsigned long long>> mat, int n) {
    int m = (n + 63) >> 6;
    int r = 0;
    for (int col = 0; col < n && r < n; col++) {
        int blk = col >> 6;
        unsigned long long mask = 1ULL << (col & 63);
        int piv = -1;
        for (int i = r; i < n; i++) {
            if (mat[i][blk] & mask) {
                piv = i;
                break;
            }
        }
        if (piv == -1) continue;
        swap(mat[r], mat[piv]);
        for (int i = 0; i < n; i++) {
            if (i != r && (mat[i][blk] & mask)) {
                for (int j = blk; j < m; j++) mat[i][j] ^= mat[r][j];
            }
        }
        r++;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    int blocks = (N + 63) >> 6;
    vector<vector<unsigned long long>> C(N, vector<unsigned long long>(blocks, 0));

    // Read matrix C. Accept either strings like 0101... or spaced integers.
    for (int i = 0; i < N; i++) {
        string s;
        cin >> s;
        if ((int)s.size() == N && all_of(s.begin(), s.end(), [](char ch){ return ch=='0' || ch=='1'; })) {
            for (int j = 0; j < N; j++) {
                if (s[j] == '1') C[i][j >> 6] |= 1ULL << (j & 63);
            }
        } else {
            // first token already read as one entry
            int x = stoi(s);
            if (x) C[i][0] |= 1ULL;
            for (int j = 1; j < N; j++) {
                cin >> x;
                if (x) C[i][j >> 6] |= 1ULL << (j & 63);
            }
        }
    }

    int r = rank_gf2(C, N);

    // Number of pairs (A,B) with AB = C over GF(2):
    // sum over k=r..N of (# matrices A with rank k) * (# B such that AB=C for that A)
    //
    // This simplifies to:
    // answer = product_{i=0}^{r-1} (2^N - 2^i) * sum_{t=0}^{N-r} [ 2^{r(N-r-t)} * prod_{i=0}^{t-1} (2^{N-r} - 2^i) ]
    //
    // where t = k-r.
    //
    // Derivation uses decomposition by image space containing Im(C).

    vector<long long> pow2(N + 1);
    for (int i = 0; i <= N; i++) pow2[i] = modpow(2, i);

    long long pref = 1;
    for (int i = 0; i < r; i++) {
        pref = pref * ((pow2[N] - pow2[i] + MOD) % MOD) % MOD;
    }

    int m = N - r;
    long long sum = 0;
    long long prod = 1; // prod_{i=0}^{t-1}(2^m - 2^i)
    for (int t = 0; t <= m; t++) {
        long long term = modpow(2, 1LL * r * (m - t)) * prod % MOD;
        sum += term;
        if (sum >= MOD) sum -= MOD;
        if (t < m) {
            prod = prod * ((pow2[m] - pow2[t] + MOD) % MOD) % MOD;
        }
    }

    long long ans = pref * sum % MOD;
    cout << ans << '\n';
    return 0;
}

