public class Main {
    static final long MOD = 1_000_000_007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[][] C = new int[N][N];
        for (int i = 0; i < N; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < N; j++) C[i][j] = line.charAt(j) - '0';
        }
        // Compute rank of C over GF(2)
        int k = rankGF2(C, N);
        // Gaussian binomial [n choose m]_2
        // Precompute gauss[n][m] for n,m up to N
        long[][] gauss = new long[N+1][N+1];
        for (int n = 0; n <= N; n++) {
            gauss[n][0] = 1;
            for (int m = 1; m <= n; m++) {
                // [n choose m] = [n-1 choose m-1] * 2^(n-m) ... use recurrence
                // gauss[n][m] = gauss[n-1][m] * 2^m + gauss[n-1][m-1] ... no
                // [n choose m]_2 = [n-1 choose m-1]_2 + 2^(n-m)*[n-1 choose m]_2... not right
                // Correct: product formula
            }
        }
        // Use product formula: [n choose m]_2 = prod_{i=0}^{m-1} (2^(n-i)-1)/(2^(m-i)-1)
        // Compute directly
        long ans = 0;
        for (int r = k; r <= N; r++) {
            long ways = gaussBinom(N-k, r-k);
            long sr = 0;
            for (int j = 0; j <= r; j++) {
                long term = gaussBinom(r, j);
                term = term % MOD * pow2(j*N) % MOD;
                if ((r-j) % 2 == 0) sr = (sr + term) % MOD;
                else sr = (sr - term + MOD) % MOD;
            }
            long contrib = ways % MOD * sr % MOD * pow2((long)(N-r)*N) % MOD;
            ans = (ans + contrib) % MOD;
        }
        System.out.println(ans);
    }
    static long gaussBinom(int n, int m) {
        if (m < 0 || m > n) return 0;
        long num = 1, den = 1;
        for (int i = 0; i < m; i++) {
            num = num * ((pow2(n-i) - 1 + MOD) % MOD) % MOD;
            den = den * ((pow2(m-i) - 1 + MOD) % MOD) % MOD;
        }
        return num * modInv(den) % MOD;
    }
    static long pow2(long e) { return modPow(2, e, MOD); }
    static long modPow(long b, long e, long mod) { long r=1; b%=mod; while(e>0){if((e&1)==1)r=r*b%mod;b=b*b%mod;e>>=1;} return r; }
    static long modInv(long a) { return modPow(a, MOD-2, MOD); }
    static int rankGF2(int[][] mat, int N) {
        int[][] m = new int[N][N];
        for(int i=0;i<N;i++) m[i]=mat[i].clone();
        int rank=0;
        for(int col=0;col<N&&rank<N;col++){
            int pivot=-1;
            for(int row=rank;row<N;row++) if(m[row][col]==1){pivot=row;break;}
            if(pivot==-1) continue;
            int[] tmp=m[rank];m[rank]=m[pivot];m[pivot]=tmp;
            for(int row=0;row<N;row++) if(row!=rank&&m[row][col]==1) for(int c=0;c<N;c++) m[row][c]^=m[rank][c];
            rank++;
        }
        return rank;
    }
}

