public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[][] C = new int[N][N];
        for (int i = 0; i < N; i++) {
            String line = sc.next();
            for (int j = 0; j < N; j++) {
                C[i][j] = line.charAt(j) - '0';
            }
        }

        // Compute rank of C over GF(2)
        int rankC = rank(C, N);

        // Precompute powers of 2
        long[] pow2 = new long[N+1];
        pow2[0] = 1;
        for (int i = 1; i <= N; i++) {
            pow2[i] = pow2[i-1] * 2 % MOD;
        }

        // Precompute products prod_{i=0}^{r-1} (2^N - 2^i) mod MOD
        long[] prodN = new long[N+1];
        prodN[0] = 1;
        for (int r = 1; r <= N; r++) {
            prodN[r] = prodN[r-1] * ((pow2[N] - pow2[r-1] + MOD) % MOD) % MOD;
        }

        // Precompute prod_{i=0}^{r-1} (2^r - 2^i) mod MOD for each r
        long[] prodR = new long[N+1];
        prodR[0] = 1;
        for (int r = 1; r <= N; r++) {
            prodR[r] = prodR[r-1] * ((pow2[r] - pow2[r-1] + MOD) % MOD) % MOD;
        }

        // Precompute inverse of prodR
        long[] invProdR = new long[N+1];
        invProdR[N] = modInv(prodR[N]);
        for (int r = N-1; r >= 0; r--) {
            invProdR[r] = invProdR[r+1] * ((pow2[r+1] - pow2[r] + MOD) % MOD) % MOD;
        }

        // Precompute Gaussian binomial coefficients (N-s choose r-s)_2
        // gauss[N-s][r-s]
        long[][] gauss = new long[N+1][N+1];
        for (int n = 0; n <= N; n++) {
            gauss[n][0] = gauss[n][n] = 1;
            for (int k = 1; k < n; k++) {
                gauss[n][k] = (gauss[n-1][k-1] * ((pow2[n] - pow2[n-k] + MOD) % MOD) % MOD
                             + gauss[n-1][k]) % MOD;
                // Actually correct recurrence:
                // (n choose k)_2 = (n-1 choose k-1)_2 * (2^n - 2^{n-k})/(2^k - 1)?? simpler: use product formula.
            }
        }
        // Better compute directly
        long[][] gauss2 = new long[N+1][N+1];
        for (int n = 0; n <= N; n++) {
            for (int k = 0; k <= n; k++) {
                gauss2[n][k] = gaussian(n, k, pow2);
            }
        }

        long ans = 0;
        for (int r = rankC; r <= N; r++) {
            long ways = gauss2[N - rankC][r - rankC];
            ways = ways * prodN[r] % MOD;
            ways = ways * invProdR[r] % MOD;
            ways = ways * modPow(pow2[N], N - r) % MOD;
            ans = (ans + ways) % MOD;
        }

        System.out.println(ans);
    }

    static int rank(int[][] mat, int n) {
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) System.arraycopy(mat[i], 0, a[i], 0, n);
        int rank = 0;
        int row = 0;
        for (int col = 0; col < n && row < n; col++) {
            int sel = -1;
            for (int i = row; i < n; i++) {
                if (a[i][col] != 0) {
                    sel = i;
                    break;
                }
            }
            if (sel == -1) continue;
            int[] tmp = a[row];
            a[row] = a[sel];
            a[sel] = tmp;
            for (int i = row+1; i < n; i++) {
                if (a[i][col] != 0) {
                    for (int j = col; j < n; j++) {
                        a[i][j] ^= a[row][j];
                    }
                }
            }
            row++;
            rank++;
        }
        return rank;
    }

    static long gaussian(int n, int k, long[] pow2) {
        if (k < 0 || k > n) return 0;
        long num = 1, den = 1;
        for (int i = 0; i < k; i++) {
            num = num * ((pow2[n] - pow2[i] + MOD) % MOD) % MOD;
            den = den * ((pow2[k] - pow2[i] + MOD) % MOD) % MOD;
        }
        return num * modInv(den) % MOD;
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long modInv(long a) {
        return modPow(a, MOD - 2);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] rows = new long[N];
        for (int i = 0; i < N; i++) {
            String s = fs.next();
            long mask = 0L;
            for (int j = 0; j < N; j++) {
                if (s.charAt(j) == '1') mask |= 1L << j;
            }
            rows[i] = mask;
        }

        int rank = rankGF2(rows, N);

        long ans = 1;
        ans = modPow(2, (long) N * (2L * N - rank), MOD);
        for (int i = 0; i < rank; i++) {
            long term = (modPow(2, rank, MOD) - modPow(2, i, MOD) + MOD) % MOD;
            ans = (ans * term) % MOD;
        }

        System.out.println(ans);
    }

    // Computes rank of N x N binary matrix over GF(2).
    // rows[i] stores row i as bitmask.
    static int rankGF2(long[] rows, int N) {
        long[] a = rows.clone();
        int r = 0;
        for (int col = 0; col < N; col++) {
            int pivot = -1;
            for (int i = r; i < N; i++) {
                if (((a[i] >> col) & 1L) != 0) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;

            long tmp = a[r];
            a[r] = a[pivot];
            a[pivot] = tmp;

            for (int i = 0; i < N; i++) {
                if (i != r && (((a[i] >> col) & 1L) != 0)) {
                    a[i] ^= a[r];
                }
            }
            r++;
        }
        return r;
    }

    static long modPow(long a, long e, long mod) {
        long res = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) != 0) res = (res * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return res;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
